package com.atelier.tasks.controller;
import com.atelier.tasks.dto.ApiDtos.*;import com.atelier.tasks.entity.*;import com.atelier.tasks.mapper.TaskMapper;import com.atelier.tasks.repository.*;import org.springframework.web.bind.annotation.*;import java.security.Principal;import java.time.*;import java.time.temporal.TemporalAdjusters;import java.util.*;
@RestController @RequestMapping("/api/dashboard") @org.springframework.transaction.annotation.Transactional(readOnly=true) public class DashboardController {
 private final TaskRepository tasks;private final TaskActivityRepository activities;private final UserRepository users;public DashboardController(TaskRepository t,TaskActivityRepository a,UserRepository u){tasks=t;activities=a;users=u;}private AppUser user(Principal p){return users.findByEmailIgnoreCase(p.getName()).orElseThrow();}
 private LocalDate today(String timezone){try{return LocalDate.now(ZoneId.of(timezone==null?"UTC":timezone));}catch(Exception e){return LocalDate.now(ZoneOffset.UTC);}}
 @GetMapping("/stats") public Stats stats(Principal p,@RequestParam(defaultValue="UTC") String timezone){AppUser u=user(p);long total=tasks.countByOwnerId(u.id),done=tasks.countByOwnerIdAndStatus(u.id,Task.TaskStatus.COMPLETED),progress=tasks.countByOwnerIdAndStatus(u.id,Task.TaskStatus.IN_PROGRESS),pending=tasks.countByOwnerIdAndStatus(u.id,Task.TaskStatus.TODO),upcoming=tasks.countByOwnerIdAndDueDateBetweenAndStatusNot(u.id,today(timezone),today(timezone).plusDays(7),Task.TaskStatus.COMPLETED);return new Stats(total,done,pending,progress,upcoming,total==0?0.0:Math.round((done*1000.0/total))/10.0);}
 @GetMapping("/today") public List<TaskView> today(Principal p,@RequestParam(defaultValue="UTC") String timezone){LocalDate d=today(timezone);return tasks.findAllByOwnerIdAndDueDateBetweenOrderByDueDateAsc(user(p).id,d,d).stream().map(TaskMapper::toView).toList();}
 @GetMapping("/upcoming") public List<TaskView> upcoming(Principal p,@RequestParam(defaultValue="UTC") String timezone,@RequestParam(defaultValue="14") int days){LocalDate d=today(timezone);return tasks.findAllByOwnerIdAndDueDateBetweenOrderByDueDateAsc(user(p).id,d,d.plusDays(Math.max(1,Math.min(90,days)))).stream().filter(t->t.status!=Task.TaskStatus.COMPLETED).map(TaskMapper::toView).toList();}
 @GetMapping("/recent-activity") public List<ActivityView> recent(Principal p){return activities.findTop20ByUserIdOrderByCreatedAtDesc(user(p).id).stream().map(a->new ActivityView(a.id,a.task==null?null:a.task.id,a.task==null?"Deleted task":a.task.title,a.action,a.details,a.createdAt)).toList();}
}
